package migracion;
import config.ConexionBD;import java.sql.*;
public final class MigracionModeloPagoOnlineP42 {private MigracionModeloPagoOnlineP42(){}public static void main(String[]a){aplicar();}public static void aplicar(){try(Connection c=ConexionBD.obtenerConexion()){String db=c.getCatalog();col(c,db,"preferencia_externa_id","VARCHAR(150) NULL AFTER referencia_externa");col(c,db,"pago_externo_id","VARCHAR(150) NULL AFTER preferencia_externa_id");idx(c,db,"uk_ordenes_pago_proveedor_preferencia","UNIQUE KEY uk_ordenes_pago_proveedor_preferencia (proveedor,preferencia_externa_id)");idx(c,db,"idx_ordenes_pago_pago_externo","KEY idx_ordenes_pago_pago_externo (proveedor,pago_externo_id)");System.out.println("MIGRACION_P42_OK");}catch(SQLException e){throw new RuntimeException("No se pudo aplicar P4.2.",e);}}private static void col(Connection c,String db,String n,String d)throws SQLException{if(!ex(c,"SELECT 1 FROM information_schema.columns WHERE table_schema=? AND table_name='ordenes_pago' AND column_name=?",db,n))exec(c,"ALTER TABLE ordenes_pago ADD COLUMN "+n+" "+d);}private static void idx(Connection c,String db,String n,String d)throws SQLException{if(!ex(c,"SELECT 1 FROM information_schema.statistics WHERE table_schema=? AND table_name='ordenes_pago' AND index_name=?",db,n))exec(c,"ALTER TABLE ordenes_pago ADD "+d);}private static boolean ex(Connection c,String q,String...v)throws SQLException{try(PreparedStatement s=c.prepareStatement(q)){for(int i=0;i<v.length;i++)s.setString(i+1,v[i]);try(ResultSet r=s.executeQuery()){return r.next();}}}private static void exec(Connection c,String q)throws SQLException{try(Statement s=c.createStatement()){s.execute(q);}}}
